{"command":"python3 -c "
import os, glob, hashlib, json, re, subprocess

known_legitimate_keys = {
    'ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQC7vbqajDhA...'
}

suspicious_keywords = [
    '/tmp', '/var/tmp', '/dev/shm', '/run/shm',
    'attacker', 'backdoor', 'malicious', 'evil.com',
    'curl', 'wget', 'base64', 'eval', '| bash', '| sh',
    'nc ', 'netcat', 'python', 'perl', 'ruby', 'socket'
]

artifacts = []

def get_sha256(filepath):
    try:
        with open(filepath, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()
    except Exception:
        return None

def resolve_path(p):
    try:
        return os.path.realpath(p)
    except Exception:
        return os.path.abspath(p)

def extract_user_from_path(filepath):
    # Match /home/username/.ssh/authorized_keys or /root/.ssh/authorized_keys
    p = resolve_path(filepath)
    if '/root/' in p or p.startswith('/root'):
        return 'root'
    m = re.search(r'/home/([^/]+)/', p)
    if m:
        return m.group(1)
    return None

# --- Scan Cron Jobs ---
cron_files = set()

# System locations
for glob_pattern in ['/etc/cron.d/*', '/etc/crontab', '/var/spool/cron/crontabs/*', '/var/spool/cron/*', '/etc/cron.hourly/*', '/etc/cron.daily/*', '/etc/cron.weekly/*', '/etc/cron.monthly/*']:
    for p in glob.glob(glob_pattern):
        if os.path.isfile(p) and not os.path.basename(p).startswith('.'):
            cron_files.add(p)

# Target locations
if os.path.exists('/app_target'):
    for root, dirs, files in os.walk('/app_target'):
        for f in files:
            if f.startswith('.'):
                continue
            full_p = os.path.join(root, f)
            if 'cron' in full_p:
                cron_files.add(full_p)

for filepath in cron_files:
    real_p = resolve_path(filepath)
    if not os.path.isfile(real_p):
        continue
    try:
        sha256 = get_sha256(real_p)
        with open(real_p, 'r', errors='ignore') as f:
            for line_num, line in enumerate(f, 1):
                clean_line = line.strip()
                if not clean_line or clean_line.startswith('#'):
                    continue
                # Ignore env vars
                if re.match(r'^[A-Z0-9_]+\s*=', clean_line):
                    continue

                # Check standard cron jobs vs suspicious
                # standard: run-parts, anacron, e2scrub
                is_suspicious = False
                if any(kw in clean_line for kw in suspicious_keywords):
                    is_suspicious = True
                elif '/app_target/' in clean_line or '/usr/local/' in clean_line:
                    is_suspicious = True
                elif not any(std in clean_line for std in ['/usr/bin', '/bin', '/sbin', '/usr/sbin', '/usr/lib']):
                    is_suspicious = True

                if is_suspicious:
                    artifacts.append({
                        'type': 'cron_job',
                        'path': real_p,
                        'sha256': sha256,
                        'details': {
                            'line_number': line_num,
                            'content_preview': clean_line[:100],
                            'user': None
                        }
                    })
    except Exception as e:
        pass

# --- Scan Systemd Units ---
systemd_files = set()
for glob_pattern in ['/etc/systemd/system/*', '/usr/lib/systemd/system/*', '/usr/lib/systemd/system/.*', '/run/systemd/system/*']:
    for p in glob.glob(glob_pattern):
        if os.path.isfile(p):
            systemd_files.add(p)

if os.path.exists('/app_target'):
    for root, dirs, files in os.walk('/app_target'):
        for f in files:
            full_p = os.path.join(root, f)
            if 'systemd' in full_p or full_p.endswith('.service'):
                systemd_files.add(full_p)

for filepath in systemd_files:
    real_p = resolve_path(filepath)
    filename = os.path.basename(filepath)
    if not os.path.isfile(real_p):
        continue

    # Check if hidden
    is_hidden = filename.startswith('.') or os.path.basename(real_p).startswith('.')

    try:
        sha256 = get_sha256(real_p)
        with open(real_p, 'r', errors='ignore') as f:
            content = f.read()

        exec_start_line = None
        for line in content.splitlines():
            clean = line.strip()
            if clean.startswith('ExecStart') or clean.startswith('ExecStartPre') or clean.startswith('ExecStartPost'):
                exec_start_line = clean
                break

        is_suspicious = False
        if is_hidden:
            is_suspicious = True
        elif real_p.startswith('/etc/systemd/system/') or real_p.startswith('/run/systemd/system/') or '/app_target/' in real_p:
            # Check if not symlink or custom unit
            if exec_start_line:
                if any(kw in exec_start_line for kw in suspicious_keywords) or '/app_target/' in exec_start_line or '/tmp' in exec_start_line:
                    is_suspicious = True
                elif not os.path.islink(filepath):
                    is_suspicious = True
        elif any(kw in content for kw in ['attacker', 'backdoor', 'malicious', 'evil.com']):
            is_suspicious = True

        if is_suspicious:
            preview = exec_start_line if exec_start_line else content.splitlines()[0][:100] if content else ''
            artifacts.append({
                'type': 'systemd_unit',
                'path': real_p,
                'sha256': sha256,
                'details': {
                    'line_number': None,
                    'content_preview': preview[:100],
                    'user': None
                }
            })
    except Exception:
        pass

# --- Scan rc.local ---
rc_files = ['/etc/rc.local', '/etc/rc.d/rc.local']
if os.path.exists('/app_target'):
    for root, dirs, files in os.walk('/app_target'):
        for f in files:
            if f == 'rc.local':
                rc_files.append(os.path.join(root, f))

for filepath in set(rc_files):
    if not os.path.exists(filepath):
        continue
    real_p = resolve_path(filepath)
    if not os.path.isfile(real_p):
        continue
    try:
        sha256 = get_sha256(real_p)
        with open(real_p, 'r', errors='ignore') as f:
            for line_num, line in enumerate(f, 1):
                clean_line = line.strip()
                if not clean_line or clean_line.startswith('#'):
                    continue
                if clean_line in ['exit 0', 'exit 1', 'exit']:
                    continue

                artifacts.append({
                    'type': 'rc_local',
                    'path': real_p,
                    'sha256': sha256,
                    'details': {
                        'line_number': line_num,
                        'content_preview': clean_line[:100],
                        'user': None
                    }
                })
    except Exception:
        pass

# --- Scan SSH keys ---
ssh_files = set(glob.glob('/home/*/.ssh/authorized_keys') + glob.glob('/root/.ssh/authorized_keys'))
if os.path.exists('/app_target'):
    for root, dirs, files in os.walk('/app_target'):
        for f in files:
            if f == 'authorized_keys':
                ssh_files.add(os.path.join(root, f))

for filepath in ssh_files:
    real_p = resolve_path(filepath)
    if not os.path.isfile(real_p):
        continue
    user = extract_user_from_path(filepath)
    try:
        sha256 = get_sha256(real_p)
        with open(real_p, 'r', errors='ignore') as f:
            for line_num, line in enumerate(f, 1):
                clean_line = line.strip()
                if not clean_line or clean_line.startswith('#'):
                    continue

                # Check key
                is_unauthorized = False
                if any(kw in clean_line for kw in ['attacker', 'backdoor', 'malicious', 'unknown']):
                    is_unauthorized = True
                elif clean_line not in known_legitimate_keys:
                    is_unauthorized = True

                if is_unauthorized:
                    artifacts.append({
                        'type': 'ssh_key',
                        'path': real_p,
                        'sha256': sha256,
                        'details': {
                            'line_number': line_num,
                            'content_preview': clean_line[:100],
                            'user': user
                        }
                    })
    except Exception:
        pass

# Sort artifacts
artifacts.sort(key=lambda x: (x['type'], x['path'], x['details']['line_number'] if x['details']['line_number'] is not None else 0))

# Deduplicate identical items if any
unique_artifacts = []
seen = set()
for a in artifacts:
    key = (a['type'], a['path'], a['details']['line_number'])
    if key not in seen:
        seen.add(key)
        unique_artifacts.append(a)

summary = {
    'total_artifacts': len(unique_artifacts),
    'cron_jobs': sum(1 for a in unique_artifacts if a['type'] == 'cron_job'),
    'systemd_units': sum(1 for a in unique_artifacts if a['type'] == 'systemd_unit'),
    'rc_local_modifications': sum(1 for a in unique_artifacts if a['type'] == 'rc_local'),
    'ssh_keys': sum(1 for a in unique_artifacts if a['type'] == 'ssh_key')
}

report = {
    'summary': summary,
    'artifacts': unique_artifacts
}

print(json.dumps(report, indent=2))
""}

