        sha256 = get_sha256(real_p)
        if not sha256:
            continue

        with open(real_p, 'r', errors='ignore') as f:
            for line_num, line in enumerate(f, 1):
                clean_line = line.strip()
                if not clean_line or clean_line.startswith('#'):
                    continue
                if clean_line in ['exit 0', 'exit 1', 'exit']:
                    continue

                artifacts.append({
                    'type': 'rc_local',
                    'path': real_p,
                    'sha256': sha256,
                    'details': {
                        'line_number': line_num,
                        'content_preview': clean_line[:100],
                        'user': None
                    }
                })
    except Exception:
        pass

# --- 4. SSH KEYS ---
ssh_files = set(glob.glob('/home/*/.ssh/authorized_keys') + glob.glob('/root/.ssh/authorized_keys'))
if os.path.exists('/app_target'):
    for root, dirs, files in os.walk('/app_target'):
        for f in files:
            if f == 'authorized_keys':
                ssh_files.add(os.path.join(root, f))

for filepath in ssh_files:
    try:
        real_p = resolve_path(filepath)
        if not os.path.isfile(real_p):
            continue
        sha256 = get_sha256(real_p)
        if not sha256:
            continue
        user = extract_user_from_path(filepath)

        with open(real_p, 'r', errors='ignore') as f:
            for line_num, line in enumerate(f, 1):
                clean_line = line.strip()
                if not clean_line or clean_line.startswith('#'):
                    continue

                is_unauthorized = False
                if any(kw in clean_line for kw in ['attacker', 'backdoor', 'malicious', 'unknown']):
                    is_unauthorized = True
                elif clean_line not in known_legitimate_keys:
                    is_unauthorized = True

                if is_unauthorized:
                    artifacts.append({
                        'type': 'ssh_key',
                        'path': real_p,
                        'sha256': sha256,
                        'details': {
                            'line_number': line_num,
                            'content_preview': clean_line[:100],
                            'user': user
                        }
                    })
    except Exception:
        pass

# Deduplicate
unique_artifacts = []
seen = set()
for a in artifacts:
    key = (a['type'], a['path'], a['details']['line_number'])
    if key not in seen:
        seen.add(key)
        unique_artifacts.append(a)

unique_artifacts.sort(key=lambda x: (x['type'], x['path'], x['details']['line_number'] if x['details']['line_number'] is not None else 0))

summary = {
    'total_artifacts': len(unique_artifacts),
    'cron_jobs': sum(1 for a in unique_artifacts if a['type'] == 'cron_job'),
    'systemd_units': sum(1 for a in unique_artifacts if a['type'] == 'systemd_unit'),
    'rc_local_modifications': sum(1 for a in unique_artifacts if a['type'] == 'rc_local'),
    'ssh_keys': sum(1 for a in unique_artifacts if a['type'] == 'ssh_key')
}

report = {
    'summary': summary,
    'artifacts': unique_artifacts
}

print(json.dumps(report, indent=2))
""}

