    if not os.path.isfile(real_p):
        continue

    is_hidden = filename.startswith('.') or real_filename.startswith('.')

    sha256 = get_sha256(real_p)
    if not sha256:
        continue

    try:
        with open(real_p, 'r', errors='ignore') as f:
            content = f.read()
    except Exception:
        continue

    exec_start_line = None
    for line in content.splitlines():
        clean = line.strip()
        if clean.startswith('ExecStart') or clean.startswith('ExecStartPre') or clean.startswith('ExecStartPost'):
