import os
import glob
import hashlib
import json
import re
import sys

def resolve_path(p):
    try:
        return os.path.realpath(p)
    except Exception:
        return os.path.abspath(p)

def get_sha256(filepath):
    try:
        with open(filepath, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()
    except Exception:
        return None

def extract_user_from_path(filepath):
    for check_p in [filepath, resolve_path(filepath)]:
        if '/root/' in check_p or check_p.startswith('/root/') or check_p == '/root/.ssh/authorized_keys':
            return 'root'
        m = re.search(r'/home/([^/]+)/', check_p)
        if m:
            return m.group(1)
    return None

known_legitimate_keys = {
    'ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQC7vbqajDhA...'
}

suspicious_keywords = [
    '/tmp', '/var/tmp', '/dev/shm', '/run/shm',
    'attacker', 'backdoor', 'malicious', 'evil.com',
    'curl', 'wget', 'base64', 'eval', '| bash', '| sh',
    'nc ', 'netcat', 'python', 'perl', 'ruby', 'socket.socket'
]

standard_cron_cmds = [
    'run-parts', 'anacron', 'e2scrub_all', 'e2scrub_all_cron', 'apt-compat'
]

artifacts = []

# --- 1. CRON JOBS ---
cron_files = set()
for p in ['/etc/crontab', '/app_target/etc/crontab']:
    if os.path.isfile(p):
        cron_files.add(p)

for glob_pat in [
    '/etc/cron.d/*', '/var/spool/cron/crontabs/*', '/var/spool/cron/*',
    '/etc/cron.hourly/*', '/etc/cron.daily/*', '/etc/cron.weekly/*', '/etc/cron.monthly/*',
    '/app_target/etc/cron.d/*', '/app_target/var/spool/cron/crontabs/*', '/app_target/var/spool/cron/*',
    '/app_target/etc/cron.hourly/*', '/app_target/etc/cron.daily/*', '/app_target/etc/cron.weekly/*', '/app_target/etc/cron.monthly/*'
]:
    for p in glob.glob(glob_pat):
        if os.path.isfile(p) and not os.path.basename(p).startswith('.'):
